def check_occurences(tuples_list):
    result = {}
    for tup in tuples_list:
        # Ensure tuples are stored in sorted order
        sorted_tup = tuple(sorted(tup))
        if sorted_tup in result:
            result[sorted_tup] += 1
        else:
            result[sorted_tup] = 1
    return result
