def max_sub_array_sum_repeated(arr, n, k):
    def kadane(array):
        """Helper function to compute the maximum sum of a contiguous subarray using Kadane's Algorithm."""
        max_ending_here = max_so_far = array[0]
        for num in array[1:]:
            max_ending_here = max(num, max_ending_here + num)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Compute the sum of the entire array
    array_sum = sum(arr)

    # If k == 1, the array is not repeated, so just use Kadane's algorithm
    if k == 1:
        return kadane(arr)

    # Compute Kadane's algorithm on the single array and the double array
    max_single = kadane(arr)  # Max sum for the array repeated once
    max_double = kadane(arr * 2)  # Max sum for the array repeated twice

    # If the sum of the array is positive, the middle repeated portions add value
    if array_sum > 0:
        return max(max_double, max_single + (k - 2) * array_sum)
    else:
        # If the sum of the array is non-positive, the maximum subarray sum is within two copies
        return max_double
